, y: v.y, z: v.z };\n\n      let target;\n      let kpX = 4.2, kdX = 3.4;\n      let kpZ = 5.0, kdZ = 3.9;\n      let kpY = 6.2, kdY = 4.0;\n\n      if (obs.gateIndex < 3) {\n        const gate = obs.nextGate.centre;\n        if (targetIndex !== obs.gateIndex) {\n          targetIndex = obs.gateIndex;\n          phase = obs.gateIndex > 0 ? 'depart' : 'align';\n          settle = 0;\n        }\n\n        // Ensure we safely clear the previous gate plane before turning in Z/Y\n        if (phase === 'depart' && obs.gateIndex > 0) {\n          const prevGate = GATES[obs.gateIndex - 1];\n          if (p.x < prevGate.x + 0.22) {\n            target = { x: prevGate.x + 0.35, y: prevGate.y, z: prevGate.z };\n            kpZ = 6.5; kdZ = 4.5;\n            kpY = 6.8; kdY = 4.4;\n          } else {\n            phase = 'align';\n            settle = 0;\n          }\n        }\n\n        const dy = p.y - gate.y;\n        const dz = p.z - gate.z;\n\n        if (phase === 'align') {\n          target = { x: gate.x - 0.42, y: gate.y, z: gate.z };\n          // If drone is near or past the current gate plane while unaligned, route around safely\n          if (p.x > gate.x - 0.15 && (Math.abs(dy) > 0.15 || Math.abs(dz) > 0.085)) {\n            target = { x: gate.x - 0.48, y: Math.min(2.4, gate.y + 0.65), z: gate.z };\n          }\n          // Also if close to previous gate x while moving in Z/Y, keep x safely ahead of previous gate\n          if (obs.gateIndex > 0) {\n            const prevGate = GATES[obs.gateIndex - 1];\n            if (p.x < prevGate.x + 0.18) {\n              target.x = Math.max(target.x, prevGate.x + 0.30);\n            }\n          }\n\n          const distAlign = Math.hypot(target.x - p.x, dy, dz);\n          const speed = Math.hypot(v.x, v.y, v.z);\n          if (\n            distAlign < 0.13 &&\n            speed < 0.42 &&\n            Math.abs(dy) < 0.075 &&\n            Math.abs(dz) < 0.048 &&\n            Math.abs(v.z) < 0.16 &&\n            Math.abs(v