CALL write_to_file: {"CodeContent": "// Smooth continuous corridor flight controller without discrete align/cross kinks.\n// Uses smooth spatial S-curves between gates, continuous speed modulation based on\n// gate-center alignment, and a critically-damped vertical landing column.\nexport default function makeController() {\n  let targetIndex = -1, phase = 'approach', settle = 0;\n  const estMass = 0.725;\n  let distX = 0, distY = 0, distZ = 0;\n  let fastDistX = 0, fastDistY = 0, fastDistZ = 0;\n  let ix = 0, iy = 0, iz = 0, iyaw = 0;\n  let prevVel = null, prevAccCmd = { x: 0, y: 9.81, z: 0 };\n  let posF = null, velF = null;\n  let descendY = 0.46;\n\n  const GATES = [\n    { x: -1.15, y: 1.05, z: -0.85 },\n    { x: 0.15, y: 1.40, z: 0.25 },\n    { x: 1.35, y: 1.05, z: 1.05 },\n  ];\n\n  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));\n  const smoothstep = (a, b, x) => {\n    const u = clamp((x - a) / (b - a), 0, 1);\n    return u * u * (3 - 2 * u);\n  };\n\n  return {\n    step(obs) {\n      const dt = 0.01;\n      const pRaw = obs.pos, vRaw = obs.vel, att = obs.att, rates = obs.rates;\n\n      if (!posF) {\n        posF = { x: pRaw.x, y: pRaw.y, z: pRaw.z };\n        velF = { x: vRaw.x, y: vRaw.y, z: vRaw.z };\n      } else {\n        posF.x = 0.74 * pRaw.x + 0.26 * (posF.x + velF.x * dt);\n        posF.y = 0.74 * pRaw.y + 0.26 * (posF.y + velF.y * dt);\n        posF.z = 0.74 * pRaw.z + 0.26 * (posF.z + velF.z * dt);\n        velF.x = 0.60 * vRaw.x + 0.40 * velF.x;\n        velF.y = 0.60 * vRaw.y + 0.40 * velF.y;\n        velF.z = 0.60 * vRaw.z + 0.40 * velF.z;\n      }\n\n      const p = posF, v = velF;\n\n      if (prevVel && p.y > 0.12) {\n        const axMeas = (v.x - prevVel.x) / dt;\n        const ayMeas = (v.y - prevVel.y) / dt;\n        const azMeas = (v.z - prevVel.z) / dt;\n\n        const errAx = axMeas - prevAccCmd.x;\n        const errAy = ayMeas - (prevAccCmd.y - 9.81);\n        const errAz = azMeas - prevAccCmd.z;\n\n        distX = c