        target = { x: xTarget, y: yRef, z: zRef };\n          vDes = { x: vxCmd, y: dyDx * vxCmd, z: dzDx * vxCmd };\n\n          // Boost transverse stiffness when near any gate plane\n          if (dxGate < 0.45 || (gIdx > 0 && p.x < GATES[gIdx - 1].x + 0.25)) {\n            kpZ = 8.8; kdZ = 5.6;\n            kpY = 8.2; kdY = 5.0;\n          }\n        }\n      } else {\n        const pad = obs.pad.centre;\n        if (targetIndex !== 3) {\n          targetIndex = 3;\n          phase = 'approach';\n          settle = 0;\n          ix = 0; iz = 0;\n        }\n        const horizErr = Math.hypot(pad.x - p.x, pad.z - p.z);\n        const horizVel = Math.hypot(v.x, v.z);\n\n        if (phase === 'approach') {\n          const prevGate = GATES[2];\n          // Smooth S-curve from Gate 3 exit (x = 1.50) to landing pad center (2.05, 1.65)\n          const x0 = prevGate.x + 0.16, x1 = pad.x - 0.08;\n          const u = clamp((p.x - x0) / (x1 - x0), 0, 1);\n          const s = u * u * (3 - 2 * u);\n          const dsdx = u > 0 && u < 1 ? (6 * u * (1 - u)) / (x1 - x0) : 0;\n\n          const yRef = prevGate.y + (0.46 - prevGate.y) * s;\n          const zRef = prevGate.z + (pad.z - prevGate.z) * s;\n\n          const dxPad = pad.x - p.x;\n          const vxCmd = clamp(1.8 * dxPad, 0, 0.75);\n          target = {\n            x: p.x < prevGate.x + 0.16 ? prevGate.x + 0.34 : pad.x,\n            y: yRef,\n            z: zRef,\n          };\n          vDes = { x: vxCmd, y: (0.46 - prevGate.y) * dsdx * vxCmd, z: (pad.z - prevGate.z) * dsdx * vxCmd };\n\n          kpX = 5.4; kdX = 4.5;\n          kpZ = 6.2; kdZ = 4.8;\n\n          if (horizErr < 0.048 && horizVel < 0.14 && Math.abs(p.y - 0.46) < 0.10) {\n            settle++;\n          } else {\n            settle = Math.max(0, settle - 1);\n          }\n          if (settle >= 8 || obs.t > 21.0) {\n            phase = 'descend';\n            descendY = p.y;\n          }\n        }\n\n        if (phase === 'descend') {\n          const descendRate = descendY > 0.20 ? 0.38 : 0.18;\n          if (horizErr < 0.10 || obs.t > 23.0) {\n            descendY = Math.max(0.02, descendY - descendRate * dt);\n          }\n          target = { x: pad.x, y: descendY, z: pad.z };\n          vDes = { x: 0, y: descendY > 0.025 ? -descendRate * 0.65 : 0, z: 0 };\n\n          kpX = 6.8; kdX = 5.0;\n          kpZ = 6.8; kdZ = 5.0;\n          kpY = 6.8; kdY = 4.6;\n        }\n      }\n\n      const ex = target.x - p.x;\n      const ey = target.y - p.y;\n      const ez = target.z - p.z;\n\n      if (Math.abs(ex) < 0.28 && Math.abs(v.x) < 0.40) ix = clamp(ix + ex * dt, -0.45, 0.45);\n      else ix *= 0.96;\n      if (Math.abs(ez) < 0.28 && Math.abs(v.z) < 0.40) iz = clamp(iz + ez * dt, -0.45, 0.45);\n      else iz *= 0.96;\n      if (Math.abs(ey) < 0.28 && Math.abs(v.y) < 0.40) iy = clamp(iy + ey * dt, -0.45, 0.45);\n      else iy *= 0.96;\n\n      const compX = 0.55 * distX + 0.45 * fastDistX;\n      const compZ = 0.55 * distZ + 0.45 * fastDistZ;\n      const compY = 0.65 * distY + 0.35 * fastDistY;\n\n      const dragCompX = (0.42 / estMass) * v.x;\n      const dragCompZ = (0.42 / estMass) * v.z;\n\n      const ax = clamp(kpX * ex + kdX * (0.55 * vDes.x - v.x) + 1.8 * ix - compX + 0.55 * dragCompX, -4.2, 4.2);\n      const az = clamp(kpZ * ez + kdZ * (0.55 * vDes.z - v.z) + 2.0 * iz - compZ + 0.55 * dragCompZ, -4.2, 4.2);\n      const ay = clamp(kpY * ey + kdY * (0.55 * vDes.y - v.y) + 1.8 * iy - compY, -4.0, 5.2);\n\n      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);\n      const axBody = cy * ax - sy * az;\n      const azBody = sy * ax + cy * az;\n\n      const gEff = Math.max(5.5, 9.81 + ay);\n      let pitch = clamp(Math.atan2(axBody, gEff), -0.48, 0.48);\n      let roll = clamp(Math.atan2(-azBody, gEff), -0.48, 0.48);\n\n      const tiltCos = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));\n      let thrust = (estMass * (9.81 + ay)) / (16 * tiltCos);\n\n      if (obs.gateIndex === 3 && 